INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(8801, '1 Kings 18:20', '1 Kings', 18, 20, '&nbsp;نو اخى‌اب ټول اِسرائيليان او د بعل پېغمبران راغونډ کړل چې د کرمل په غر مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8802, '1 Kings 18:21', '1 Kings', 18, 21, '&nbsp;الياس د خلقو په مخکښې ودرېدو او ورته يې وفرمائيل، ”ترڅو پورې به تاسو په دوو عقيدو کښې ګډ وډ يئ؟ کۀ مالِک خُدائ، خُدائ پاک وى، نو هغۀ پسې روان شئ، خو کۀ بعل خُدائ وى، نو هغۀ پسې روان شئ.“ خو خلقو هيڅ هم ونۀ وئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8803, '1 Kings 18:22', '1 Kings', 18, 22, '&nbsp;بيا الياس وفرمائيل، ”د مالِک خُدائ په پېغمبرانو کښې صرف زۀ پاتې يم، خو د بعل پېغمبران څلور نيم سوه سړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8804, '1 Kings 18:23', '1 Kings', 18, 23, '&nbsp;دوه غوَيان راولئ، وړومبے دې د بعل پېغمبران خوښ کړى، حلال دې کړى، ټوټې ټوټې دې کړى او په لرګو باندې دې کېږدى، خو اور دې نۀ بلوى. او زۀ به د هغه بل غوَيى سره هم دغه شان وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8805, '1 Kings 18:24', '1 Kings', 18, 24, '&nbsp;نو تاسو خپل خُدائ ته سوال وکړئ او زۀ به مالِک خُدائ ته سوال وکړم او چې په جواب کښې کوم يو خُدائ اور راولېږى، نو هغه رښتونے خُدائ پاک دے.“ خلقو چغې کړې چې، ”تۀ ټيک وائې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8806, '1 Kings 18:25', '1 Kings', 18, 25, '&nbsp;بيا الياس د بعل پېغمبرانو ته وفرمائيل، ”تاسو ډېر يئ نو ځکه، اول تاسو يو غوَيے بوځئ او تيار يې کړئ او خپل خُدائ ته سوال وکړئ، خو په لرګو اور مۀ بلوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8807, '1 Kings 18:26', '1 Kings', 18, 26, '&nbsp;چې کوم غوَيے ورله راوستلے شوے وو نو هغوئ هغه بوتلو، تيار يې کړو او د سحر نه تر غرمې پورې يې بعل ته سوال کولو. هغوئ چغې وهلې، ”بعله، مونږ ته څۀ ووايه.“ خو هيڅ جواب نۀ راتلو. او چې کومه قربان‌ګاه يې جوړه کړې وه د هغې نه ګېرچاپېره ګډېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8808, '1 Kings 18:27', '1 Kings', 18, 27, '&nbsp;د غرمې په وخت الياس ورپورې ټوقې شروع کړې، ”ښۀ په زوره چغې وهئ، ځکه چې هغه خُدائ دے. کېدے شى چې هغه د ورځې خوبونه وينى، يا په متيازو ناست وى، يا په سفر تلے وى. يا اودۀ وى، راويښ يې کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8809, '1 Kings 18:28', '1 Kings', 18, 28, '&nbsp;نو پېغمبرانو چغې نورې هم تېزې کړې او د خپل رسم په مطابق يې په چاکوانو او په نېزو خپل ځانونه دومره غوڅ کړل، چې په وينه لت پت شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8810, '1 Kings 18:29', '1 Kings', 18, 29, '&nbsp;هغوئ ټول مازيګر تر ماښامه پورې چغې وهلې او ګډې وډې يې وئيلې، خو څۀ جواب رانۀ غلو او هيڅ آواز وانۀ ورېدلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8811, '1 Kings 18:30', '1 Kings', 18, 30, '&nbsp;بيا الياس خلقو ته وفرمائيل، ”ما له نزدې راشئ.“ او هغوئ ټول ترې نه راغونډ شول. الياس د مالِک خُدائ د قربان‌ګاه مرمت کول شروع کړل کومه چې راغورزولے شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8812, '1 Kings 18:31', '1 Kings', 18, 31, '&nbsp;هغۀ د يعقوب د دولسو زامنو د قبيلو دپاره يو يو کاڼے واخستلو. يعقوب هغه څوک وو چې مالِک خُدائ د اِسرائيل نوم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8813, '1 Kings 18:32', '1 Kings', 18, 32, '&nbsp;د دې کاڼو سره هغۀ د مالِک خُدائ د عبادت دپاره قربان‌ګاه جوړه کړه. هغۀ د دې نه ګېرچاپېره يوه کنده وکنستله، دومره لويه چې تقريباً څوارلس ليټره اوبۀ په کښې راتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8814, '1 Kings 18:33', '1 Kings', 18, 33, '&nbsp;بيا هغۀ لرګى په قربان‌ګاه باندې کېښودل، غوَيے يې ټوټې ټوټې کړو او په لرګو يې کېښودو. هغۀ وفرمائيل، ”دا څلور منګى د اوبو نه ډک کړئ او په نذرانه او لرګو باندې يې واچوئ.“ نو هغوئ هم داسې وکړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8815, '1 Kings 18:34', '1 Kings', 18, 34, '&nbsp;او هغۀ وفرمائيل، ”دا بيا وکړئ،“ نو هغوئ بيا داسې وکړل. هغۀ بيا وفرمائيل چې داسې يو ځل بيا وکړئ، نو هغوئ په درېم ځل هم داسې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8816, '1 Kings 18:35', '1 Kings', 18, 35, '&nbsp;اوبۀ د قربان‌ګاه نه لاندې ګېرچاپېره وبهېدې او هغه کنده يې ډکه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8817, '1 Kings 18:36', '1 Kings', 18, 36, '&nbsp;د مازيګر نذرانې په وخت کښې الياس پېغمبر قربان‌ګاه ته نزدې شو او سوال يې وکړو، ”اے مالِکه خُدايه، د اِبراهيم، اِسحاق او د يعقوب خُدايه پاکه، نن دا ثابِته کړه چې تۀ د اِسرائيل خُدائ پاک يې او زۀ ستا خِدمت کوونکے يم او دا هر څۀ ما ستا په حُکم کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8818, '1 Kings 18:37', '1 Kings', 18, 37, '&nbsp;مالِکه خُدايه، زما سوال واوره، زما سوال واوره، نو چې دې خلقو ته پته ولګى چې تۀ، مالِک خُدائ، خُدائ پاک يې او تۀ د هغوئ زړونه ځان ته بيا را اړوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8819, '1 Kings 18:38', '1 Kings', 18, 38, '&nbsp;نو مالِک خُدائ اور نازل کړو او دې اور نذرانه، لرګى او کاڼى وسوزول، زمکه يې اوچه کړه او په هغه کنده کښې يې اوبۀ اوچې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8820, '1 Kings 18:39', '1 Kings', 18, 39, '&nbsp;کله چې خلقو دا وليدل، نو هغوئ پړمخې په زمکې پرېوتل او وې وئيل، ”مالِک خُدائ، خُدائ پاک دے، صِرف مالِک خُدائ، خُدائ پاک دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8821, '1 Kings 18:40', '1 Kings', 18, 40, '&nbsp;الياس حُکم وکړو، ”د بعل پېغمبران ونيسئ، چې يو هم درنه ونۀ تښتى.“ خلقو هغه ټول ونيول او الياس هغوئ لاندې قيسون سيند ته بوتلل او وې وژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8822, '1 Kings 18:41', '1 Kings', 18, 41, '&nbsp;بيا الياس اخى‌اب بادشاه ته وفرمائيل، ”اوس لاړ شه او خوراک څښاک وکړه. زۀ د يو دروند باران شور اورم چې راروان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8823, '1 Kings 18:42', '1 Kings', 18, 42, '&nbsp;کله چې اخى‌اب د خوراک او څښاک دپاره لاړو، نو الياس د کرمل غرۀ سر ته وختلو، هلته هغه ټيټ شو او سر يې په زمکه ولګولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8824, '1 Kings 18:43', '1 Kings', 18, 43, '&nbsp;هغۀ خپل نوکر ته وفرمائيل، ”لاړ شه او د سمندر طرف ته وګوره.“ نوکر لاړو او بيا راغلو او وې وئيل، ”ما خو هيڅ هم ونۀ ليدل.“ الياس اووۀ ځل هغۀ ته وفرمائيل چې لاړ شه او وګوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8825, '1 Kings 18:44', '1 Kings', 18, 44, '&nbsp;په اوؤم ځل هغه راواپس شو او وې وئيل، ”ما يوه وړه وريځ وليده چې د سړى د لاس برابره وه او د سمندر نه راروانه وه.“ الياس خپل نوکر له حُکم ورکړو، چې، ”اخى‌اب بادشاه له لاړ شه او هغۀ ته ووايه چې جنګى ګاډۍ تياره کړى، په کښې سور شى او کور ته زر راواپس شى ګنې باران به يې رايسار کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8826, '1 Kings 18:45', '1 Kings', 18, 45, '&nbsp;په لږ وخت کښې آسمان په تکه توره وريځ باندې پټ شو، هوا راغله او ورسره دروند باران هم شروع شو. اخى‌اب په خپله جنګى ګاډۍ کښې سور شو او يزرعيل ته واپس روان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8827, '1 Kings 18:46', '1 Kings', 18, 46, '&nbsp;د مالِک خُدائ طاقت په الياس باندې راغلو، هغۀ خپله چُوغه په ملا پورې وتړله او تر يزرعيل پورې يې د اخى‌اب نه وړاندې منډې وهلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8828, '1 Kings 19:1', '1 Kings', 19, 1, '&nbsp;الياس چې څۀ کړى وُو او چې ټول پېغمبران يې وژلى وُو نو اخى‌اب بادشاه خپلې ښځې ايزبل ته هغه هر څۀ ووئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8829, '1 Kings 19:2', '1 Kings', 19, 2, '&nbsp;نو هغې الياس له پېغام ورولېږلو، ”خپل خُدايان دې ما ووژنى چې سبا په دې وخت زۀ تا سره هغه کار ونۀ کړم کوم چې تا د هغه پېغمبرانو سره کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8830, '1 Kings 19:3', '1 Kings', 19, 3, '&nbsp;الياس ويرېدو او د خپل ژوند بچ کولو دپاره وتښتېدو، هغۀ خپل نوکر ځان سره بوتلو او په يهوداه کښې بيرسبع ته لاړو او خپل نوکر يې هلته پرېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8831, '1 Kings 19:4', '1 Kings', 19, 4, '&nbsp;الياس په بيابان کښې ټوله ورځ مزل وکړو. هغۀ مزل بس کړو او د جارُو د ونې د سورى لاندې کښېناستو او هغۀ غوښتل چې مړ شى. هغۀ ووئيل، ”مالِکه خُدايه، بس دے، ما ووژنه، زۀ د خپل پلار نيکۀ نه ښۀ نۀ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8832, '1 Kings 19:5', '1 Kings', 19, 5, '&nbsp;هغه د جارُو د ونې لاندې څملاستو او اودۀ شو. ناڅاپه يوې فرښتې هغۀ له لاس وروړو او ورته يې وفرمائيل، ”پاڅه او وخوره.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8833, '1 Kings 19:6', '1 Kings', 19, 6, '&nbsp;هغۀ ګېرچاپېره وکتل او يوه روټۍ يې وليده چې په ګرمو سکارو باندې پخه شوې وه او خپل سر سره نزدې يې د اوبو يو منګے وليدو. هغۀ خوراک څښاک وکړو او بيا څملاستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8834, '1 Kings 19:7', '1 Kings', 19, 7, '&nbsp;د مالِک خُدائ فرښته بيا راغله او په دوېم ځل يې هغه پاڅولو، ورته يې وفرمائيل، ”پاڅه او وخوره، ګنې ستا دپاره به سفر ډېر ګران وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8835, '1 Kings 19:8', '1 Kings', 19, 8, '&nbsp;الياس پاڅېدو، خوراک څښاک يې وکړو او دې خوراک هغۀ له دومره طاقت ورکړو چې سينا ته څلوېښت ورځې مزل وکړى، کوم چې د خُدائ پاک غر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8836, '1 Kings 19:9', '1 Kings', 19, 9, '&nbsp;هلته هغه يو غار ته ورننوتلو او شپه يې په کښې تېره کړه. او د مالِک خُدائ کلام پرې نازل شو چې، ”الياسه، تۀ دلته څۀ کوې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8837, '1 Kings 19:10', '1 Kings', 19, 10, '&nbsp;هغۀ ورته وفرمائيل، ”مالِکه خُدايه، ما په شوق سره ستا خِدمت کړے دے، ما صِرف ستا خدمت کړے دے، اے مالِک خُدايه ربُ الافواجه. خو اِسرائيليانو تا سره خپل لوظ مات کړے دے، ستا قربان‌ګاه يې ماتې کړې دى او ستا پېغمبران يې وژلى دى. صِرف زۀ پاتې يم او هغوئ زما په ژوند پسې لګېدلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8838, '1 Kings 19:11', '1 Kings', 19, 11, '&nbsp;مالِک خُدائ هغۀ ته وفرمائيل، ”بهر لاړ شه او د غرۀ په سر باندې زما په وړاندې ودرېږه.“ بيا مالِک خُدائ تېر شو او يوه زبردسته هوا يې راولېږله چې هغې غرونه وشلول او کاڼى يې دړې وړې کړل، خو مالِک خُدائ په هوا کښې نۀ وو. هوا بنده شوه او بيا زلزله راغله، خو مالِک خُدائ په زلزله کښې هم نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8839, '1 Kings 19:12', '1 Kings', 19, 12, '&nbsp;د زلزلې نه پس اور راغلو، خو مالِک خُدائ په اور کښې هم نۀ وو. او د اور نه پس، يو نرے آواز راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8840, '1 Kings 19:13', '1 Kings', 19, 13, '&nbsp;کله چې الياس آواز واورېدو، نو هغۀ خپل مخ په چُوغه کښې پټ کړو، بهر لاړو او د غار په خولۀ کښې ودرېدو. او هغۀ ته يو آواز وشو چې، ”الياسه، تۀ دلته څۀ کوې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8841, '1 Kings 19:14', '1 Kings', 19, 14, '&nbsp;هغه ورته وفرمائيل، ”مالِکه خُدايه، ربُ الافواجه، ما په تا باندې غېرت کړے دے. خو اِسرائيليانو تا سره خپل لوظ مات کړے دے، ستا قربان‌ګاه يې ماتې کړې دى او ستا پېغمبران يې وژلى دى. صِرف زۀ پاتې يم او هغوئ زما د وژلو کوشش هم کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8842, '1 Kings 19:15', '1 Kings', 19, 15, '&nbsp;مالِک خُدائ وفرمائيل، ”دمشق ته نزدې بيابان ته واپس شه، بيا ښار ته ورننوځه او حِزائيل د شام بادشاه مقرر کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8843, '1 Kings 19:16', '1 Kings', 19, 16, '&nbsp;د نِمسى زوئ ياهُو د اِسرائيل بادشاه مقرر کړه او ابيل‌محوله د سافط زوئ اليشع ستا نه پس پېغمبر مقرر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8844, '1 Kings 19:17', '1 Kings', 19, 17, '&nbsp;هر څوک چې د حِزائيل نه ژوندے خلاص شى نو د ياهُو په ذريعه به ووژلے شى او هر څوک چې د ياهُو نه وتښتى نو اليشع به هغه ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8845, '1 Kings 19:18', '1 Kings', 19, 18, '&nbsp;خو زۀ به بيا هم په اِسرائيل کښې اووۀ زره کسان ژوندى پرېږدم، هغه ټول چې زما وفادار وى او بعل ته يې سجده نۀ وى کړې او هغه ټول چې د هغوئ خُلو هغه بُت ښُکل کړے نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8846, '1 Kings 19:19', '1 Kings', 19, 19, '&nbsp;الياس لاړو او وې ليدل چې اليشع د غوَيو په يوه قلبه باندې يوه کوله، د هغۀ نه مخکښې يوولس سړى د قلبو سره وُو او هر يو سړى په يوه قلبه باندې يوه کوله. نو الياس خپله پېغمبرى چُوغه وويستله او اليشع ته يې ورواغوستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8847, '1 Kings 19:20', '1 Kings', 19, 20, '&nbsp;نو اليشع خپل غوَيان پرېښودل، په الياس پسې يې منډه کړه او ورته يې وفرمائيل، ”زۀ به خپل مور پلار په مخه ښه وئيلو دپاره ښُکل کړم، نو بيا به تا سره لاړ شم.“ الياس ورته وفرمائيل، ”ټيک ده، لاړ شه. خو چې ما ستا دپاره څۀ کړى دى نو هغه مۀ هېروه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8848, '1 Kings 19:21', '1 Kings', 19, 21, '&nbsp;بيا اليشع د خپلې قلبې غوَيو له لاړو او حلال يې کړل او د دې غوښه يې پخه کړه، د جغ نه يې د خشاک کار واخستو. هغۀ غوښه خلقو له ورکړه او هغوئ وخوړله. بيا هغه الياس پسې د هغۀ د نوکر په شان لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8849, '1 Kings 20:1', '1 Kings', 20, 1, '&nbsp;د شام بادشاه بِن‌حدد خپل ټول فوج راغونډ کړو او دوه دېرشو نورو بادشاهانو يې د خپلو آسونو او جنګى ګاډو سره ملګرتيا کوله، هغه روان شو، سامريه يې محاصره کړه او په دې باندې يې د حملې تيارے وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8850, '1 Kings 20:2', '1 Kings', 20, 2, '&nbsp;هغۀ ښار ته پېغام وړُونکى ولېږل چې د اِسرائيل بادشاه اخى‌اب ته ووائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8851, '1 Kings 20:3', '1 Kings', 20, 3, '&nbsp;”بِن‌حدد بادشاه غواړى چې تۀ هغۀ ته خپل سپين زر او سرۀ زر حواله کړې او خپلې ښې ښځې او بچى هم ورکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8852, '1 Kings 20:4', '1 Kings', 20, 4, '&nbsp;اخى‌اب ورته ووئيل، ”بِن‌حدد ته ووايئ چې، بادشاه سلامت، زۀ تيار يم، زۀ او زما هر څۀ ستا شول.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8853, '1 Kings 20:5', '1 Kings', 20, 5, '&nbsp;وروستو پېغام وړُونکى د بِن‌حدد د دې بلې مطالبې سره بيا راغلل، ”ما تا له خبر درلېږلے وو چې تۀ به ما ته خپل سپين زر او سرۀ زر او خپلې ښځې او بچى حواله کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8854, '1 Kings 20:6', '1 Kings', 20, 6, '&nbsp;خو اوس به زۀ خپل آفسران درولېږم چې ستا محل او ستا د آفسرانو کورونه ولټوى او چې د هغوئ څۀ هم خوښ شى نو هغه به ترېنه را اوچت کړى. هغوئ به سبا تقريباً دا وخت هلته وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8855, '1 Kings 20:7', '1 Kings', 20, 7, '&nbsp;اخى‌اب بادشاه د مُلک ټول مشران راغوښتل او ورته يې ووئيل، ”تاسو ته پته ده چې دا سړے مونږ تباه کول غواړى. هغۀ ما له يو پېغام راولېږلو چې زما نه يې زما ښځې، بچى، سپين زر او سرۀ زر غوښتل او ما دا خبره ومنله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8856, '1 Kings 20:8', '1 Kings', 20, 8, '&nbsp;خو مشرانو او خلقو ورته ووئيل، ”هغه چې څۀ وائى نو هغه کار مۀ کوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8857, '1 Kings 20:9', '1 Kings', 20, 9, '&nbsp;نو اخى‌اب د بِن‌حدد پېغام وړونکو ته ووئيل، ”بادشاه سلامت ته ووايئ چې ما د هغۀ وړومبۍ مطالبه ومنله، خو دا دوېمه نۀ شم منلے.“ نو پېغام وړُونکى بِن‌حدد له د دې جواب سره واپس راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8858, '1 Kings 20:10', '1 Kings', 20, 10, '&nbsp;نو د بِن‌حدد نه يې دا پېغام راوړو، ”ما دې خُدايان ووهى او مړ مې دې کړى کۀ د سامريه دومره خاوره هم پاتې شى چې زما فوجيان يې په موټى کښې راواخلى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8859, '1 Kings 20:11', '1 Kings', 20, 11, '&nbsp;اخى‌اب بادشاه ورته ووئيل، ”بِن‌حدد بادشاه ته ووايئ چې تکړه فوجى د جنګ نه مخکښې نۀ بلکې وروستو لافې وهى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8860, '1 Kings 20:12', '1 Kings', 20, 12, '&nbsp;بِن‌حدد ته د اخى‌اب جواب په هغه وخت کښې مِلاو شو چې هغۀ او نورو بادشاهانو په خپلو خېمو کښې مے څښل. هغۀ خپلو سړو له حُکم ورکړو چې په ښار باندې د حملې دپاره تيار شئ، نو هغوئ د جنګ دپاره صفونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8861, '1 Kings 20:13', '1 Kings', 20, 13, '&nbsp;نو يو پېغمبر اخى‌اب بادشاه له ورَغلو او ورته يې وفرمائيل، ”مالِک خُدائ فرمائى چې تۀ دا لوئ لښکر وينې؟ هم نن به زۀ تا له په دې باندې فتح درکړم او تا ته به پته ولګى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8862, '1 Kings 20:14', '1 Kings', 20, 14, '&nbsp;اخى‌اب ترې نه تپوس وکړو، ”د حملې مشرى به څوک کوى؟“ پېغمبر ورته وفرمائيل، ”مالِک خُدائ فرمائى چې د ضِلعو د حکمرانانو د مشرۍ لاندې به ځوانان فوجيان حمله وکړى.“ بادشاه ترې نه تپوس وکړو، ”جنګ به څوک شروع کړى؟“ پېغمبر ورته وفرمائيل، ”تۀ به يې شروع کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8863, '1 Kings 20:15', '1 Kings', 20, 15, '&nbsp;نو بادشاه زلمى فوجيان راوغوښتل چې هغوئ د ضِلعو د حکمرانانو د مشرۍ لاندې وُو، دا ټول دوه سوه او دوه دېرش وُو. بيا هغۀ د اِسرائيل لښکر راوغوښتلو چې ټول اووۀ زره سړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8864, '1 Kings 20:16', '1 Kings', 20, 16, '&nbsp;د اِسرائيل لښکر د غرمې په وخت د جنګ دپاره راووتل، چې په دې وخت کښې بِن‌حدد او د هغۀ دوه دېرش ملګرى په خپلو خېمو کښې نشه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8865, '1 Kings 20:17', '1 Kings', 20, 17, '&nbsp;اول زلمى فوجيان وړاندې لاړل. بِن‌حدد چې کوم جاسوسان لېږلى وُو نو هغوئ ورته ووئيل چې، ”څۀ فوجيان د سامريه نه راروان دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8866, '1 Kings 20:18', '1 Kings', 20, 18, '&nbsp;هغۀ حُکم وکړو، ”کۀ هغوئ د جنګ يا د صُلحې دپاره راروان وى نو ژوندى يې ونيسئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8867, '1 Kings 20:19', '1 Kings', 20, 19, '&nbsp;زلمى فوجيانو د جنګ مشرى کوله، چې د اِسرائيل لښکر ورپسې وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8868, '1 Kings 20:20', '1 Kings', 20, 20, '&nbsp;او هر فوجى يو يو دشمن ووژلو. شاميان وتښتېدل، اِسرائيليان ورپسې وُو، خو بِن‌حدد او د هغۀ ملګرى په آسونو باندې وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8869, '1 Kings 20:21', '1 Kings', 20, 21, '&nbsp;اخى‌اب بادشاه راووتلو، په آسونو او جنګى ګاډو باندې يې حمله وکړه او شاميانو له يې يو مضبوط شکست ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8870, '1 Kings 20:22', '1 Kings', 20, 22, '&nbsp;بيا پېغمبر اخى‌اب بادشاه له لاړو او ورته يې وفرمائيل، ”واپس لاړ شه او خپل فوجيان تيار کړه او صحيح منصوبې جوړې کړه، ځکه چې د شام بادشاه به په راتلونکى سپرلى کښې بيا حمله کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8871, '1 Kings 20:23', '1 Kings', 20, 23, '&nbsp;د بِن‌حدد آفسرانو هغۀ ته ووئيل، ”د بنى اِسرائيلو خُدايان د غرونو خُدايان دى، نو ځکه اِسرائيل مونږ له شکست راکړو. خو کۀ مونږ د هغوئ سره په مېدانونو کښې جنګ وکړُو نو مونږ به يقيناً هغوئ له شکست ورکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8872, '1 Kings 20:24', '1 Kings', 20, 24, '&nbsp;نو هغه دوه دېرش بادشاهان د مشرۍ نه لرې کړه او د هغوئ په ځائ فوجى مشران مقرر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8873, '1 Kings 20:25', '1 Kings', 20, 25, '&nbsp;بيا د هغه لښکر هومره يو بل لوئ لښکر راغونډ کړه کوم چې ستا نه تلى وُو او هم هغه هومره آسونه او جنګى ګاډۍ ورکړه. مونږ به د اِسرائيليانو سره په مېدانونو کښې جنګ وکړُو او دا ځل به هغوئ له شکست ورکړُو.“ بِن‌حدد بادشاه د هغوئ خبره ومنله او هم داسې يې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8874, '1 Kings 20:26', '1 Kings', 20, 26, '&nbsp;په ورپسې سپرلى کښې هغۀ خپل سړى راوغوښتل او د هغوئ سره افيق ښار ته روان شو چې په اِسرائيل حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8875, '1 Kings 20:27', '1 Kings', 20, 27, '&nbsp;اِسرائيليان راغونډ کړے شول او د جنګ سامان يې راواخستلو، هغوئ روان شول او شاميانو ته مخامخ يې خېمې ولګولې. اِسرائيليان د شاميانو په مقابله کښې د چېلو د دوو وړو رَمو په شان ښکارېدل خو د شاميانو نه ګېرچاپېره مُلک ډک وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8876, '1 Kings 20:28', '1 Kings', 20, 28, '&nbsp;يو پېغمبر اخى‌اب بادشاه له لاړو او ورته يې وفرمائيل، ”مالِک خُدائ داسې فرمائى چې شاميان وائى چې زۀ د مېدانونو نۀ، بلکې د غرونو خُدائ يم، نو ځکه به زۀ تاسو د هغوئ په لوئ لښکر باندې بريالى کړم او تاسو ته به پته ولګى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8877, '1 Kings 20:29', '1 Kings', 20, 29, '&nbsp;اووۀ ورځې شاميان او اِسرائيليان په خپلو خېمو کښې يو بل ته مخامخ ايسار وُو. په اوومه ورځ باندې هغوئ جنګ شروع کړو او بنى اِسرائيلو يو لاک شاميان ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8878, '1 Kings 20:30', '1 Kings', 20, 30, '&nbsp;او باقى ژوندى پاتې شوى افيق ښار ته وتښتېدل، چرته چې د هغوئ په اوويشت زره سړو باندې د ښار دېوالونه راوغورزېدل. بِن‌حدد هم ښار ته وتښتېدو او د يو کور په دنننۍ کوټه کښې پټ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8879, '1 Kings 20:31', '1 Kings', 20, 31, '&nbsp;د هغۀ آفسران ورغلل او هغۀ ته يې ووئيل، ”مونږ اورېدلى دى چې د اِسرائيل بادشاهان رحم کوونکى وى. مونږ له اجازت راکړه چې د ملا نه د ټاټ جامې او د مرۍ نه پړى تاو کړُو او د اِسرائيل بادشاه له ورشُو او کېدے شى چې هغه تا ژوندے پرېږدى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8880, '1 Kings 20:32', '1 Kings', 20, 32, '&nbsp;نو هغوئ د خپلې ملا نه د ټاټ جامې او د مرۍ نه پړى تاو کړل او اخى‌اب له لاړل او ورته يې ووئيل، ”ستا خِدمت کوونکے بِن‌حدد تا ته د خپل ژوند سوال کوى.“ اخى‌اب ورته ووئيل، ”هغه لا ژوندے دے څۀ؟ ټيک ده، هغه زما ورور دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8881, '1 Kings 20:33', '1 Kings', 20, 33, '&nbsp;د بِن‌حدد آفسران د يوې ښې خبرې په طمع وُو او چې کله اخى‌اب ووئيل چې ”ورور“ نو هغوئ فوراً پوهه شول او وې وئيل، ”لکه څنګه چې تا ووئيل، بِن‌حدد ستا ورور دے.“ نو اخى‌اب حُکم وکړو، ”هغه ما له راولئ.“ کله چې بِن‌حدد راورسېدو، نو اخى‌اب ورته ووئيل چې د هغۀ سره په جنګى ګاډۍ کښې سور شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8882, '1 Kings 20:34', '1 Kings', 20, 34, '&nbsp;بِن‌حدد هغۀ ته ووئيل، ”زما پلار چې ستا پلار نه کوم ښارونه اخستى وُو نو هغه به تا له واپس درکړم او تۀ په دمشق کښې د خپل ځان دپاره يو کاروبارى مرکز جوړولے شې، لکه څنګه چې زما پلار په سامريه کښې کړى وُو.“ اخى‌اب ورته ووئيل، ”نو په دې شرطُونو به زۀ تا آزاد کړم.“ اخى‌اب د هغۀ سره يوه معاهده وکړه او بِن‌حدد يې پرېښودو چې لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8883, '1 Kings 20:35', '1 Kings', 20, 35, '&nbsp;د مالِک خُدائ په حُکم د پېغمبرانو د قبيلې يو کس خپل ملګرى پېغمبر ته وفرمائيل چې ما ووهه. خو هغۀ اِنکار وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8884, '1 Kings 20:36', '1 Kings', 20, 36, '&nbsp;نو هغۀ ورته وفرمائيل، ”تا د مالِک خُدائ د حُکم نافرمانى کړې ده، نو په دې وجه تۀ چې څنګه زما نه لاړ شې نو يو زمرے به دې ووژنى.“ او چې څنګه هغه لاړو نو يو زمرے راغلو او هغه يې ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8885, '1 Kings 20:37', '1 Kings', 20, 37, '&nbsp;نو هم دغه پېغمبر يو بل سړى له لاړو او ورته يې وفرمائيل، ”ما ووهه،“ نو دې سړى هغه ووهلو، او دومره سخت يې ووهلو چې زخمى شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8886, '1 Kings 20:38', '1 Kings', 20, 38, '&nbsp;پېغمبر خپل مخ په پټۍ باندې وتړلو، چې خپل شکل بدل کړى او لاړو او د سړک په غاړه ودرېدو او د اِسرائيل د بادشاه د تېرېدو اِنتظار يې کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8887, '1 Kings 20:39', '1 Kings', 20, 39, '&nbsp;کوم وخت چې بادشاه تېرېدو، نو هغه پېغمبر ورته آواز وکړو او ورته يې وفرمائيل، ”بادشاه سلامت، زۀ په جنګ کښې جنګېدم چې يو فوجى ما له يو نيولے شوے دشمن راوستلو او راته يې ووئيل، دې سړى ته ګوره، کۀ دے درنه وتښتى، نو د دې سړى په بدل کښې به خپل ژوند ورکوې او يا به درې زره د سپينو زرو سيکې جرمانه ورکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8888, '1 Kings 20:40', '1 Kings', 20, 40, '&nbsp;خو زۀ په نورو کارونو کښې مصروف شوم او هغه سړے وتښتېدو.“ بادشاه ورته وفرمائيل، ”تا په خپله خبره کښې خپله فېصله کړې ده او تا ته به سزا ملاويږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8889, '1 Kings 20:41', '1 Kings', 20, 41, '&nbsp;نو پېغمبر د خپل مخ نه پټۍ لرې کړه او بادشاه هغه فوراً وپېژندو چې دا خو پېغمبر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8890, '1 Kings 20:42', '1 Kings', 20, 42, '&nbsp;بيا پېغمبر بادشاه ته وفرمائيل، ”دا د مالِک خُدائ کلام دے چې تا هغه سړى له د تښتېدو اجازت ورکړو د کوم د وژلو چې ما حُکم درکړے وو، نو د هغۀ د ژوند په بدل کښې به خپل ژوند ورکوې او ستا خلق به ځکه تباه شى چې د هغۀ خلق يې تښتېدو ته پرېښى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8891, '1 Kings 20:43', '1 Kings', 20, 43, '&nbsp;نو بادشاه په يره او خفګان کښې واپس سامريه ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8892, '1 Kings 21:1', '1 Kings', 21, 1, '&nbsp;نو په يزرعيل کښې د سامريه د اخى‌اب بادشاه د محل سره نزدې د انګورو يو باغ وو چې د نبوت نومې سړى وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8893, '1 Kings 21:2', '1 Kings', 21, 2, '&nbsp;يوه ورځ اخى‌اب نبوت ته ووئيل، ”د انګورو باغ دې ما له راکړه، دا زما د محل سره نزدې دے او زۀ د دې زمکې نه د سبزۍ باغ جوړول غواړم. زۀ به تا له د دې نه ښۀ د انګورو باغ درکړم، يا کۀ تۀ وائې نو زۀ به د دې قيمت درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8894, '1 Kings 21:3', '1 Kings', 21, 3, '&nbsp;نبوت ورته ووئيل، ”د انګورو دا باغ ما ته د پلار نيکۀ نه په ميراث کښې مِلاو شوے دے، مالِک خُدائ دې ونۀ کړى چې زۀ دا تا له درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8895, '1 Kings 21:4', '1 Kings', 21, 4, '&nbsp;اخى‌اب کور ته لاړو او چې نبوت ورته څۀ وئيلى وُو په هغې باندې خفه او غصه وو. هغه په خپل کټ کښې څملاستو، ځان يې مرَور کړو او خوراک يې نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8896, '1 Kings 21:5', '1 Kings', 21, 5, '&nbsp;د هغۀ ښځه ايزبل ورغله او تپوس يې ترې نه وکړو، ”تۀ ولې دومره خفه يې؟ او خوراک ولې نۀ کوې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8897, '1 Kings 21:6', '1 Kings', 21, 6, '&nbsp;نو هغۀ ورته ووئيل، ”دا ځکه چې نبوت يزرعيلى ته ما ووئيل چې زۀ به درنه د انګورو باغ په پېسو واخلم، يا کۀ غواړې نو زۀ به د دې باغ په ځائ بل باغ درکړم، خو هغۀ راته ووئيل، چې باغ تا له نۀ درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8898, '1 Kings 21:7', '1 Kings', 21, 7, '&nbsp;ايزبل ورته ووئيل، ”نو تۀ د اِسرائيل بادشاه يې کۀ نه؟“ د کټ نه پاڅه، ”خپل زړۀ خوشحال کړه او خوراک وکړه. زۀ به تا له د نبوت د انګورو باغ واخلم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8899, '1 Kings 21:8', '1 Kings', 21, 8, '&nbsp;بيا هغې يو څو خطونه وليکل، د اخى‌اب دستخط يې ورباندې وکړو، د هغۀ مهر يې ورباندې ولګولو او د هغه ښار آفسرانو او مشرانو ته يې ولېږل چرته چې نبوت اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8900, '1 Kings 21:9', '1 Kings', 21, 9, '&nbsp;په خطونو کښې ليکلى شوى وُو، ”اعلان وکړئ چې خلق روژه ونيسى، خلق دې راغونډ شى او نبوت له د عزت ځائ ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');